  'signup.off.body': 'આ પ્લેટફોર્મની સ્વિચ છે, તમારી સંસ્થા વિશેની વાત નથી — તે હજી છે જ નહીં. કંઈ તૂટ્યું નથી: જાતે સાઇન-અપ આ સમયે બસ ચાલુ નથી.',
  'signup.off.codeKept': 'કંઈ બન્યું નથી, અને તમે દાખલ કરેલો કોડ વપરાયો નથી.',
  'signup.err.taken': 'આ સંસ્થાનું નામ પહેલેથી લેવાઈ ગયું છે — નામ પહેલા આવો, પહેલા મેળવો ધોરણે છે. તમારો જિલ્લો અથવા કોઈ અલગ શબ્દ ઉમેરો.',
  'signup.err.reserved': 'આ નામ એવું સરનામું છે જે આ સ્ટોરફ્રન્ટ પોતાના માટે રાખે છે. તમારો જિલ્લો અથવા કોઈ અલગ શબ્દ ઉમેરો.',
  'signup.err.invalid': 'પ્લેટફોર્મે આ વિગતો સ્વીકારી નહીં. દરેક ફીલ્ડ તપાસો — કંઈ બન્યું નથી.',
  'signup.err.rate_cooldown': 'હમણાં જ કોડ મોકલાયો. તમે {n} સેકન્ડ પછી બીજો માગી શકો છો.',
  'signup.err.rate_hourly': 'છેલ્લા એક કલાકમાં આ નંબર પર {max} કોડ માગવામાં આવ્યા. તેની સુરક્ષા માટે આગળનો કોડ {minutes} મિનિટ પછી મોકલી શકાશે.',
  'signup.err.rate_ip': 'આ કનેક્શનથી ઘણી બધી વિનંતીઓ. {n} સેકન્ડ પછી ફરી પ્રયાસ કરો.',
  'signup.err.channel': 'કોડ ફક્ત SMS દ્વારા મોકલી શકાય છે.',
  'signup.err.start_again': 'એ પગલું સમાપ્ત થઈ ગયું. તમારી વિગતો ફરી ભરો — કંઈ બન્યું નથી.',
