  'signup.err.code_wrong': 'આ કોડ મેળ ખાતો નથી — આ કોડ પર {left} પ્રયાસ બાકી. કંઈ બન્યું નથી.',
  'signup.err.code_expired': 'આ કોડનો સમય પૂરો થયો અથવા તે પહેલેથી વપરાઈ ગયો — તમારી કોઈ ભૂલ નથી, અને કંઈ બન્યું નથી. નીચેથી નવો મોકલો.',
  'signup.err.code_locked': 'આ કોડ પર ઘણા ખોટા પ્રયાસ. તમે {minutes} મિનિટ પછી નવા કોડથી ફરી પ્રયાસ કરી શકો છો.',
  'signup.err.disabled': 'પ્લેટફોર્મ પર જાતે સાઇન-અપ હમણાં બંધ છે.',
  'signup.err.plan_not_offered': 'એ યોજના આ દેશમાં ઉપલબ્ધ નથી — કંઈ બન્યું નથી.',
  'signup.err.trial_unavailable': 'હમણાં ટ્રાયલ સેટ થઈ શકતો નથી (પ્લેટફોર્મની ટ્રાયલ યોજના ઉપલબ્ધ નથી) — કંઈ બન્યું નથી. કૃપા કરીને પછી પ્રયાસ કરો.',
  'signup.err.rate_signup': 'આ કનેક્શનથી ઘણા બધા સાઇન-અપ. {minutes} મિનિટ પછી ફરી પ્રયાસ કરો.',
  'signup.err.rate_verify': 'છેલ્લા એક કલાકમાં આ નંબર પર ઘણી બધી કોડ-ચકાસણી. {minutes} મિનિટ પછી ફરી પ્રયાસ કરો.',
  'signup.err.unavailable': 'અમે સાઇન-અપ સેવા સુધી પહોંચી શક્યા નહીં. કંઈ બન્યું નથી — થોડી વારમાં ફરી પ્રયાસ કરો.',
  'signup.refused.title': 'આ પેજ શું વચન આપતું નથી',
  'signup.refused.ussd': 'કોઈ મિસ્ડ-કૉલ, USSD કે અવાજ વાળું સાઇન-અપ નથી, અને કન્સોલ આજે જેટલી ભાષાઓ બોલે છે તેનાથી વધુનો દાવો નથી — અંગ્રેજી, હિન્દી અને ગુજરાતી, સિગ્નલ વાળી સ્ક્રીન પર.',
  'signup.refused.sandbox': 'કોઈ "સેન્ડબોક્સ પૈસા" નથી: ટ્રાયલમાં અલગ નકલી-પૈસા વાળો કોઈ મોડ નથી, તેથી તેનું વચન નથી.',
  'signup.refused.payments': 'ચુકવણીનું કોઈ વચન નથી: નવી સંસ્થાઓ માટે ઓનલાઇન ચુકવણી ચાલુ નથી, તેથી આ પેજ કોઈ વચન આપતું નથી.',
  'signup.refused.trace': '"દરેક લોટ પર ખેતર-થી-થાળી ટ્રેસ" નહીં: ટ્રેસેબિલિટી દરેક જગ્યાએ ચાલુ નથી, તેથી "દરેક" સાચું નહીં હોય.',
  'signup.refused.domain': '"તમારું પોતાનું ડોમેન" નહીં: તમને {platform} પર તમારા સ્ટોરફ્રન્ટનું પોતાનું સરનામું મળે છે; પોતાનું ડોમેન પછી આવશે.',
  'signup.refused.desk': 'કોઈ પાર્ટનરશિપ ડેસ્ક, ફોન નંબર, ઈ-મેલ કે કૉલબેક નથી: હેલ્પલાઇન અને કૉલબેક હજી અસ્તિત્વમાં નથી. ફૂટરનું સંપર્ક પેજ પછી આવશે.',
  'signup.refused.names': 'નામ પહેલા આવો, પહેલા મેળવો ધોરણે છે, અને કોઈ વિવાદ-નિવારણ ડેસ્ક નથી: જો તમારું નામ લેવાઈ ગયું હોય, તો તમારો જિલ્લો ઉમેરો.',
  'signup.refused.otp': 'કોડની કોઈ નક્કી અવધિ નથી અને "કોઈ મર્યાદા નહીં" નું વચન નથી: કોડની સાચી અવધિ અને નવા કોડ પહેલાંની રાહ સર્વરથી આવે છે અને જેમ છે તેમ બતાવાય છે.',
  'signup.refused.members': 'સભ્ય-સંખ્યાનું કોઈ ફીલ્ડ નથી, અને "ક્યારેય સીટ-ગણતરી નહીં" નું વચન નથી: યોજનાઓમાં સભ્ય ખેડૂતોની મર્યાદા હોય છે.',
  'signup.refused.oncall': 'નિષ્ફળ સાઇન-અપ પર કોઈને પેજ કરવામાં આવતું નથી: નિષ્ફળતા અહીં જ બતાવાય છે, ફરી પ્રયાસના વિકલ્પ સાથે.',
  'signup.refused.flag': 'સાઇન-અપ બંધ હોય ત્યારે તે પ્લેટફોર્મની સ્વિચ છે — "આ ટેનન્ટ કે યોજના માટે બંધ" નહીં: હજી કોઈ સંસ્થા છે જ નહીં.',
  'pricing.lead': '{country} ની સંસ્થાઓ માટે દરેક જાહેર યોજના, જેમ પ્લેટફોર્મ આજે યાદી કરે છે.',
