  'inputs.empty': '{org} એ હમણાં કોઈ ખેતીની સામગ્રી મૂકી નથી.',
  'store2a.browseOff.title': 'બ્રાઉઝ કરવું કામચલાઉ ઉપલબ્ધ નથી.',
  'store2a.browseOff.body': 'હમણાં આખા પ્લેટફોર્મ પર બ્રાઉઝ કરવું બંધ છે. તમારા કનેક્શનમાં કોઈ ખામી નથી — કૃપા કરી પછી પાછા આવો.',
  'store2a.refusal.title': 'આ પાનું શું બતાવતું નથી કે વચન આપતું નથી',
  'store2a.refusal.mandi': 'કોઈ મંડી (APMC) સંદર્ભ કિંમત બતાવાતી નથી — તેનો કોઈ લાઇસન્સવાળો, સ્રોત સાથેનો આધાર નથી.',
  'store2a.refusal.tellMeWhen': '“મને જણાવો” બટન નથી: મેળ ખાતો લોટ આવે ત્યારે તમને સંદેશો મોકલનાર કંઈ નથી.',
  'store2a.refusal.tellMeIfReturns': '“પાછો આવે તો જણાવો” બટન નથી: એ સંદેશો મોકલનાર કંઈ નથી.',
  'store2a.refusal.follow': '“ફોલો કરો” બટન નથી: આગળનો લોટ આવે ત્યારે તમને જણાવનાર કંઈ નથી.',
  'store2a.refusal.offline': 'અગાઉની મુલાકાતના લોટ ઑફલાઇન જોવા માટે રખાતા નથી, અને કાર્ટ ક્યારેય સિંકની રાહ જોતું નથી — કાર્ટમાં ઉમેરવું ફક્ત ઑનલાઇન થાય છે.',
  'store2a.refusal.regionRestricted': 'તમારા રાજ્ય માટે આ પરિણામોમાંથી ચુપચાપ કંઈ કાઢી નાખવામાં આવતું નથી — બ્રાઉઝિંગ પર કોઈ રાજ્ય-પ્રતિબંધ લાગુ થતો નથી.',
  'store2a.refusal.multilingual': 'શોધ એકસાથે ઘણી ભાષાઓમાં જોતી નથી અને જોડણી સુધારતી નથી.',
  'store2a.refusal.voice': 'બોલીને શોધવાની સુવિધા નથી — કૃપા કરી શબ્દો લખો.',
  'store2a.refusal.closest': 'જ્યારે કંઈ મેળ ખાતું નથી, અમે એ જ કહીએ છીએ — કોઈ “નજીકનો મેળ” અનુમાનવામાં આવતો નથી.',
  'store2a.refusal.distance': 'કોઈ “સૌથી નજીક પહેલાં”, કોઈ અંતર, કોઈ ડિલિવરી તારીખ અને કોઈ અંતર-આધારિત કિંમત બતાવાતી નથી: કોઈ સ્થાન પૂછવામાં આવતું નથી.',
  'store2a.refusal.aiGrade': 'કોઈ મશીની ગ્રેડ સૂચન અને કોઈ વિશ્વાસ-અંક બતાવાતો નથી — ફક્ત એ ગ્રેડ જેની કોઈ વ્યક્તિએ પુષ્ટિ કરી.',
  'store2a.refusal.priceFee': 'અમે એમ નથી કહેતા કે કિંમતમાં ગ્રેડિંગ કે પ્લેટફોર્મના ચાર્જ આવી જાય છે: કોઈ પણ ફી કે કર ઉમેરાય છે અને ચેકઆઉટ પર બતાવાય છે.',
  'store2a.refusal.bulk': 'કોઈ અલગ જથ્થાબંધ કે ચકાસાયેલ-ખરીદનાર કિંમત નથી — મૂકેલી કિંમત બધા માટે છે.',
  'store2a.refusal.dispatchRegrade': 'મોકલતી વખતે ગ્રેડ ફરી તપાસાતો નથી — એવું કોઈ પગલું હજી નથી.',
  'store2a.refusal.farmer': 'ખેડૂતનું નામ, ફોટો, સભ્ય નંબર, જમીન અને “ક્યારથી વેચે છે” તારીખ બતાવાતી નથી — વેચનાર સંસ્થા છે.',
  'store2a.refusal.badges': 'કોઈ “KYC ચકાસાયેલ”, “કેન્દ્ર-ગ્રેડેડ વેચનાર” કે પૂરાં થયેલાં વેચાણનો બેજ બતાવાતો નથી — સંસ્થા માટે એવું કંઈ નોંધાયું નથી.',
  'store2a.refusal.translated': 'સમીક્ષાઓ એ જ ભાષામાં બતાવાય છે જેમાં લખાઈ — તેમનો અનુવાદ થતો નથી.',
  'store2a.refusal.fifo': 'બેચ નંબર અને સમાપ્તિ તારીખ બતાવાતી નથી, અને જૂનો સ્ટોક પહેલાં મોકલવાનું વચન અપાતું નથી — હજી કોઈ ઓર્ડર સાથે કોઈ બેચ જોડાતો નથી.',
  'store2a.refusal.mrp': 'કોઈ મહત્તમ છૂટક કિંમતની મર્યાદાનો દાવો થતો નથી — આ ઉત્પાદનો માટે કોઈ MRP નોંધાઈ નથી.',
  'store2a.refusal.age': 'આ પાના પર ઉંમરની કોઈ તપાસ થતી નથી.',
  'store2a.refusal.labelHelpline': 'અહીં કોઈ કટોકટી ફોન લાઇન છાપવામાં આવતી નથી — ઉત્પાદનના પોતાના લેબલ પરની સલામતી સૂચનાઓ અનુસરો.',
  'store2a.refusal.inputsSwitch': 'ખેતીની સામગ્રીનું વેચાણ દરેક સંસ્થા માટે અલગથી ચાલુ કે બંધ થતું નથી — એવી કોઈ સેટિંગ નથી.',
