  'store2b.refusal.slabs': 'ડિલિવરી નક્કી સ્લેબ અને પ્રતિ શિપમેન્ટ ન્યૂનતમમાં લેવાતી નથી — ફક્ત સંસ્થાના પોતાના નક્કી કરેલા ચાર્જ લાગે છે, જે ચેકઆઉટ પર દેખાય છે.',
  'store2b.refusal.gst': 'ડિલિવરી પર ઉપરથી જીએસટી ઉમેરાતો નથી, અને ભાવમાં જીએસટી સામેલ હોવાનો દાવો કરાતો નથી — કર રકમમાંથી ગણાય છે, તેના પર ઉમેરાતો નથી.',
  'store2b.refusal.alternatives': 'ઉપલબ્ધ ન હોય તેવી વસ્તુના બદલે નજીકની ઊપજ સૂચવાતી નથી — તેને કાઢો, અથવા આ સ્ટોર જુઓ.',
  'store2b.refusal.offlineQueue': 'કાર્ટના ફેરફાર તમારા ફોન પર કતારમાં રખાતા નથી: ફેરફાર અમારા સર્વર સુધી પહોંચે છે અથવા સ્પષ્ટ રીતે નિષ્ફળ જાય છે, અને તમને જણાવાય છે.',
  'store2b.refusal.savedOnPhone': 'આ ફોન પર કંઈ સાચવાતું નથી — તમારું કાર્ટ અમારા સર્વર પર છે; લોડ ન થાય તો પાનું એ જણાવે છે અને ફરી પ્રયાસ કરવા દે છે.',
  'store2b.refusal.guestCart': 'આ ડિવાઇસ પર કોઈ મહેમાન કાર્ટ નથી — કાર્ટ સાઇન-ઇન થયેલા ખરીદનારનું હોય છે.',
  'store2b.refusal.licenceUpload': 'કોઈ લાઇસન્સ અપલોડ નથી અને કોઈ લાઇસન્સ તપાસ નથી: ખરીદનાર લાઇસન્સ પ્રક્રિયા હજી અસ્તિત્વમાં નથી, તેથી લાઇસન્સવાળું ઉત્પાદન અહીં ખરીદી શકાતું નથી.',
  'store2b.refusal.age': 'કોઈ ઉંમરની તપાસ થતી નથી — જન્મ તારીખ લેવાતી નથી.',
  'store2b.refusal.oncall': 'નિષ્ફળ કાર્ટ ફેરફાર કોઈને જાણ કરતો નથી; તે તમને નામથી બતાવાય છે, અને તમે ફરી પ્રયાસ કરી શકો છો.',
  'store2b.refusal.audit': 'કાર્ટ કોઈ ઓડિટ નોંધ લખતું નથી અને કોઈ પૈસા ખસેડતું નથી — તમે સ્વીકારેલો ભાવ ઓર્ડર મૂકતી વખતે તેના પર નક્કી થાય છે.',
  'store2b.refusal.flagTenantPlan': 'જ્યારે ખરીદી થોભે છે, ત્યારે પ્લેટફોર્મ પર બધા માટે થોભે છે — કોઈ એક સંસ્થા કે યોજના માટે નહીં, અને તેનું કોઈ સ્ટોર સેટિંગ નથી.',
  'store2b.refusal.threeSteps': 'ચેકઆઉટનાં ત્રણ પગલાં છે — સરનામું, ચુકવણી, સમીક્ષા — પણ એસ્ક્રો-પુષ્ટિનું કોઈ અલગ પગલું નથી: પૈસા ફક્ત તમે ચૂકવો ત્યારે લેવાય છે.',
