  'store5a.refusal.voice': '"બોલીને લખો" નથી: સમીક્ષાઓ કોઈ પણ ભાષામાં ટાઇપ થાય છે. કંઈ રેકોર્ડ કે લિપ્યંતર થતું નથી.',
  'store5a.refusal.photos': 'સમીક્ષામાં ફોટા ઉમેરી શકાતા નથી — હજી ફોટાની ચકાસણીની વ્યવસ્થા નથી.',
  'store5a.refusal.offline': 'પછી મોકલવા માટે આ ફોન પર કંઈ સાચવાતું નથી: મોકલવું નિષ્ફળ જાય તો આ પેજ કહે છે અને તમે ફરી પ્રયાસ કરી શકો છો.',
  'store5a.refusal.tonight': 'રેટિંગ રાતના અપડેટની રાહ જોતું નથી — સંસ્થાનું રેટિંગ થોડી જ મિનિટોમાં અપડેટ થાય છે.',
  'store5a.refusal.maskedName': 'તમારી સમીક્ષા સાથે ક્યારેય કોઈ નામ, આદ્યાક્ષર કે શહેર બતાવાતું નથી — ફક્ત "ચકાસાયેલ ખરીદનાર".',
  'store5a.refusal.gradingDesk': 'કોઈ ગ્રેડિંગ ડેસ્ક કે કોલ્ડ-ચેન તપાસ વિગતવાર રેટિંગ વાંચતી નથી.',
  'store5a.refusal.orgHide': 'સંસ્થા તમારી સમીક્ષા છુપાવી, બદલી કે દૂર કરી શકતી નથી — તે જવાબ આપી શકે છે અને તેને પ્લેટફોર્મ ડેસ્ક માટે ફ્લેગ કરી શકે છે.',
  'store5a.refusal.flaggedOff': 'અહીં બદલવા જેવી કોઈ સ્ટોર સેટિંગ નથી — સમીક્ષાઓ બંધ હોય ત્યારે આ પેજ કહે છે.',
  'store5a.refusal.reconcile': 'સમીક્ષા કરવાથી કોઈ પૈસા ફરતા નથી — મેળ બેસાડવા જેવું કંઈ નથી.',
  'store5a.refusal.oncall': 'નિષ્ફળતા પર કોઈને સૂચના મોકલાતી નથી — તે અહીં જ કહેવાય છે, અને તમે ફરી પ્રયાસ કરી શકો છો.',
  'store5a.refusal.voiceFirst': 'કોઈ અવાજ-પ્રથમ મોડ નથી: આ સ્ટોર પર કંઈ સાંભળતું કે વાંચીને સંભળાવતું નથી.',
  'store5a.refusal.speaks': 'બટનો સ્પર્શ કરતાં બોલતા નથી; સિનિયર ખેડૂત મોડ ફક્ત અક્ષરો અને બટનો મોટા કરે છે.',
  'store5a.refusal.helper': 'મોડ કોઈ મદદનીશ સેટ કરતું નથી કે અવાજથી પુષ્ટિ થતી નથી; તે આ જ ડિવાઇસ પર ચાલુ થાય છે.',
  'store5a.refusal.everywhere': 'કોઈ મોડ તમારા બીજા ફોન કે બ્રાઉઝર પર લાગુ થતો નથી — દરેક ડિવાઇસ પોતાનું રાખે છે.',
  'store5a.refusal.phoneLine': 'અહીં સમાન માર્ગ તરીકે કોઈ ફોન લાઇન કે શૉર્ટ-કોડ મેનુ અપાતું નથી.',
  'store5a.refusal.sellerPreview': 'આ પેજ પર વેચાણનું કોઈ પૂર્વદર્શન બતાવાતું નથી — તે તમારા માટે આ સ્ટોર કેવો દેખાય તેના વિશે છે.',
  'store5a.refusal.unaudited': 'હજી દાવો નથી: કે રંગ એકલો ક્યારેય અર્થ આપતો નથી, કે સ્ક્રીન રીડર માટે વાંચવાનો ક્રમ — તેની ચકાસણી હજી થઈ નથી.',
