  'store5a.a11y.lead': 'મોડ સાથે ચાલે છે — કોઈ પણ મેળ ચાલુ કરો.',
  'store5a.a11y.deviceOnly': 'ફક્ત આ જ ડિવાઇસ પર રખાય છે: બીજો ફોન કે બ્રાઉઝર પોતાનું રાખે છે.',
  'store5a.a11y.saved': 'આ ડિવાઇસ પર સાચવ્યું.',
