  'store5a.a11y.mode.motion': 'શાંત ગતિ',
  'store5a.a11y.what.senior': 'આ ડિવાઇસના દરેક પેજ પર મોટા અક્ષરો અને મોટા બટનો. કંઈ દૂર થતું નથી — ફક્ત ફેલાવાય છે.',
  'store5a.a11y.what.contrast': 'શાહી ઘેરી, કિનારીઓ જાડી અને પેજ કાગળ જેવું સફેદ થાય છે. આ બંધ હોય ત્યારે પણ તમારા ફોનની વધુ-કૉન્ટ્રાસ્ટ સેટિંગ માન્ય રહે છે.',
  'store5a.a11y.what.motion': 'કોઈ સરકવું કે ઝાંખું થવું નહીં — વસ્તુઓ સીધી દેખાય અને જાય છે. આ બંધ હોય ત્યારે પણ તમારા ફોનની ઓછી-ગતિ સેટિંગ માન્ય રહે છે.',
