  'store6.offline.states.offlineName': 'સિગ્નલ ન હોય ત્યારે',
  'store6.offline.states.offline': 'એક પટ્ટી શબ્દોમાં આ કહે છે, અને સર્વરવાળા દરેક બટન પર "સિગ્નલ જોઈએ" લખાય છે. જે છતાં ચાલે છે:',
  'store6.offline.works.thisPage': 'આ પેજ, આ નિયમો સાથે કે શું રાહ જુએ છે અને શું નહીં.',
  'store6.offline.works.needsSignal': 'જે કામ માટે સર્વર જોઈએ, તેનું બટન કારણ સાથે આ કહે છે — પછી મોકલવા માટે કંઈ રખાતું નથી.',
  'store6.offline.states.slowName': 'ધીમું કનેક્શન',
  'store6.offline.states.slow': 'ધીમા માટે કોઈ અલગ રીત નથી: રાખેલું પેજ કહે છે કે તે કેટલું જૂનું છે, અને લોડ થતું પેજ બસ લોડ થાય છે.',
  'store6.offline.keep.on': '{org} તમે ખોલેલાં જાહેર પેજ — કોઈ લિસ્ટિંગ, તેનું પોતાનું પેજ, ટ્રેસ અને પ્રમાણપત્રનાં પેજ, તમે જોયેલી યાદી — આ ફોન પર રાખે છે: વધુમાં વધુ {pages} પેજ, {days} દિવસ સુધી; સાઇન-ઇન હો ત્યારે ક્યારેય નહીં, ફોટા ક્યારેય નહીં, અને તમે ન ખોલ્યું હોય તે કંઈ નહીં.',
  'store6.offline.keep.off': '{org} આ ફોન પર પેજ રાખતી નથી: સિગ્નલ ન હોય ત્યારે તમને આ પેજ દેખાય છે.',
  'store6.offline.keep.platform': 'કોઈ સંસ્થા પોતાના સ્ટોર પર તમે ખોલેલાં જાહેર પેજ આ ફોન પર રાખવા દઈ શકે — વધુમાં વધુ {pages} પેજ, {days} દિવસ સુધી; સાઇન-ઇન હો ત્યારે ક્યારેય નહીં, ફોટા ક્યારેય નહીં, તમે ન ખોલ્યું હોય તે કંઈ નહીં. પ્લેટફોર્મનાં પોતાનાં પેજ રખાતાં નથી.',
  'store6.offline.time.title': 'દરેક રાખેલું પેજ કહે છે કે તે કેટલું જૂનું છે',
  'store6.offline.time.rule': 'આ ફોનમાંથી બતાવાયેલું પેજ તે સમય બતાવે છે જ્યારે તેને રાખ્યું હતું — ઘડિયાળનો સમય અને કેટલા સમય પહેલાં.',
  'store6.offline.tier.fresh': '{minutes} મિનિટથી ઓછું જૂનું: ફક્ત "આ સમય સુધીનું" વાળી હળવી લીટી.',
  'store6.offline.tier.aging': '{minutes} મિનિટથી {hours} કલાક સુધી: "આ સમય સુધીનું" વાળી લીટી.',
  'store6.offline.tier.prominent': '{hours} કલાકથી વધુ: પેજ પર એક પટ્ટી.',
  'store6.offline.tier.full': '{hours} કલાકથી વધુ: પૂરી પહોળાઈની પટ્ટી, અને "ભાવ બદલાયા હોઈ શકે".',
  'store6.offline.time.money': '{hours} કલાક પછી રાખેલા પેજના દરેક ભાવ પર "તે સમયનો ભાવ" લખાય છે — શબ્દોમાં, ફક્ત રંગથી ક્યારેય નહીં.',
  'store6.offline.dont.title': 'જે ક્યારેય થતું નથી',
  'store6.offline.dont.staleWithoutBand': 'રાખેલો ભાવ ક્યારેય તેની પટ્ટી વગર દેખાતો નથી — જૂનો આંકડો હમણાંનો કહીને બતાવવો જૂઠ ગણાય.',
  'store6.offline.dont.blank': 'જે પેજની નકલ રાખેલી છે તે ક્યારેય ખાલી થતું નથી — નકલ તેની ઉંમર સાથે દેખાય છે.',
  'store6.offline.dont.autoRefresh': 'તમારા હાથ નીચે કંઈ આપમેળે બદલાતું નથી — પેજ ત્યારે જ બદલાય છે જ્યારે તમે તેને ફરી લોડ કરો.',
  'store6.offline.example.title': 'ઉદાહરણ — સિગ્નલ વગર એક લિસ્ટિંગ',
  'store6.offline.example.band': 'તમે તેને ખોલ્યું તે સમય સુધીનું. ભાવ બદલાયા હોઈ શકે.',
