  'store6.form.success.title': 'કંઈ ઉમેરાયું નથી',
  'store6.form.success.body': 'સિગ્નલ વગર કંઈ લાગુ થયું નથી. સિગ્નલ હોય ત્યારે લિસ્ટિંગ પર કાર્ટમાં ઉમેરો; ત્યારે દેખાતો ભાવ જ ભાવ છે.',
