  'store6.form.failure.body': 'આ સાચું છે: કંઈ મોકલાયું નથી અને કંઈ બદલાયું નથી. સિગ્નલ હોય ત્યારે લિસ્ટિંગ પર ફરી પ્રયાસ કરો.',
  'store6.form.liveAct': 'સિગ્નલ હોય ત્યારે ફરી શોધો',
  'store6.form.back': 'ઑફલાઇન નિયમો પર પાછા',
  'store6.queued.title': 'પૈસાનું કામ ક્યારેય કતારમાં નથી લાગતું',
  'store6.queued.lead': 'ચુકવણી, બોલી, ઑફરનો જવાબ, ડિલિવરીની પુષ્ટિ — જે કામમાં પૈસા ખસે કે પાકું વચન બને, તેના માટે સર્વરનો હમણાંનો જવાબ જોઈએ. સિગ્નલ ન હોય ત્યારે આ બટન કારણ સાથે આ કહે છે, અને પછી મોકલવા માટે કંઈ રખાતું નથી.',
  'store6.queued.money.title': 'પૈસા અને વચનો',
  'store6.queued.countdown.title': 'જેની સમયમર્યાદા હોય',
  'store6.queued.content.title': 'બાકીનું બધું',
  'store6.queued.content.body': 'તમારું કાર્ટ, સરનામાં, સંદેશા, સમીક્ષાઓ અને સેટિંગ પણ મોકલવા માટે સિગ્નલ માગે છે: તેમનાં બટન પણ "સિગ્નલ જોઈએ" કહે છે, અને પછી મોકલવા માટે ફોન પર કંઈ રખાતું નથી.',
  'store6.queued.coming': 'ટૂંક સમયમાં: તમારા ન મોકલેલા શબ્દો આ ફોન પર રહેશે અને ત્યારે જ જશે જ્યારે તમે મોકલો દબાવશો.',
  'store6.queued.back': 'ઑફલાઇન નિયમો પર પાછા',
  'store6.install.metaTitle': 'ઍપ અને ઇન્સ્ટોલ',
  'store6.install.title': '{name} ને તમારી હોમ સ્ક્રીન પર ઉમેરો',
  'store6.install.lead': '{name} તમારા બ્રાઉઝરમાંથી સીધું તમારી હોમ સ્ક્રીન પર ઇન્સ્ટોલ થાય છે — કોઈ ઍપ સ્ટોરની જરૂર નથી.',
  'store6.install.how.title': 'કેવી રીતે',
  'store6.install.how.android': 'Android પર, Chrome માં: મેનુ (⋮) ખોલો અને "Install app" અથવા "Add to Home screen" પસંદ કરો.',
  'store6.install.how.iphone': 'iPhone પર, Safari માં: Share દબાવો, પછી "Add to Home Screen".',
  'store6.install.how.other': 'બીજાં બ્રાઉઝરના મેનુમાં પણ આ જ પગલું હોય છે. જો તમારામાં ન હોય, તો {name} બ્રાઉઝરમાં પણ એવું જ ચાલે છે.',
  'store6.install.icon': 'તમારી હોમ સ્ક્રીન પર તે {name} છે, તેના પોતાના નામ અને નિશાન સાથે.',
  'store6.install.polite.title': 'નિયમથી વિનમ્ર',
  'store6.install.update': 'તે વિનમ્રતાથી અપડેટ થાય છે: નવું સંસ્કરણ તૈયાર થાય ત્યારે અમે કહીએ છીએ — હમણાં રિફ્રેશ કરો, અથવા આગલી વાર ખોલશો ત્યારે લાગુ થશે. તમે ફોર્મ ભરતા હો ત્યારે વચ્ચે ક્યારેય નહીં.',
  'store6.install.language': 'તે તમારી ભાષામાં ચાલે છે — એ જ જે ઇન્સ્ટોલ કરતી વખતે તમે વાપરો છો. પછી ભાષા બદલો, તો ઇન્સ્ટોલ કરેલી ઍપ આગલી વાર ખોલવાથી તે અપનાવે છે.',
  'store6.install.offline.title': 'સિગ્નલ વગર',
  'store6.install.offline.notOrders': 'તમારા ઓર્ડર અને સંદેશા આ ફોન પર રખાતા નથી — સિગ્નલ હોય ત્યારે તેમને ખોલો.',
